<div class="grid gap-5 md:grid-cols-2"><x-ui.select name="scan_id" label="Scan source" :value="$item->scan_id" :options="$scans->mapWithKeys(fn($x)=>[$x->id=>'Scan #'.$x->id.' · '.$x->source_type])" required/><x-ui.select name="product_id" label="Produit rapproché" :value="$item->product_id" :options="$products->pluck('name','id')"/><x-ui.input name="detected_name" label="Produit détecté" :value="$item->detected_name" required/><x-ui.input name="detected_brand" label="Marque détectée" :value="$item->detected_brand"/><x-ui.input name="detected_category" label="Catégorie détectée" :value="$item->detected_category"/><x-ui.input name="confidence" label="Confiance (%)" type="number" :value="$item->confidence" min="0" max="100" step="0.01"/><div class="md:col-span-2"><x-ui.textarea name="detected_composition" label="Composition détectée" :value="$item->detected_composition"/></div><div class="md:col-span-2"><x-ui.checkbox name="is_confirmed" label="Détection confirmée manuellement" :checked="$item->is_confirmed"/></div></div>
